import type {
  DefaultOptions,
  FilterDataStructure,
  Option,
} from 'models/Filters';

type SignalNode = {
  name: string;
  children: SignalNode[];
};

const signalHierarchy: SignalNode[] = [
  { name: 'Baseline', children: [] },
  {
    name: 'Execution',
    children: [
      { name: 'Bees', children: [] },
      { name: 'Buyers', children: [] },
      { name: 'SKU per POC', children: [] },
    ],
  },
  {
    name: 'External',
    children: [
      { name: 'Covid 19', children: [] },
      { name: 'FIFA 2026', children: [] },
      {
        name: 'Holidays',
        children: [
          { name: 'Carnaval', children: [] },
          { name: 'Consciencia Negra', children: [] },
          { name: 'Corpus Christi', children: [] },
          { name: 'Dia de Sao Joao', children: [] },
          { name: 'Dia do Trabalho', children: [] },
          { name: 'Finados', children: [] },
          { name: 'Independencia da Bahia', children: [] },
          { name: 'Independencia do Brasil', children: [] },
          { name: 'Natal', children: [] },
          { name: 'Nossa Senhora Aparecida', children: [] },
          { name: 'Pascoa', children: [] },
          { name: 'Proclamacao da Republica', children: [] },
          {
            name: 'Revolucao Farroupilha (Dia do Gaucho)',
            children: [],
          },
          { name: 'Sexta-feira Santa', children: [] },
          { name: 'Tiradentes', children: [] },
        ],
      },
      {
        name: 'Industry Trend',
        children: [{ name: 'Regional Trend', children: [] }],
      },
      { name: 'LDA Population', children: [] },
      {
        name: 'Macro Economics',
        children: [
          { name: 'Food Cost', children: [] },
          { name: 'Other Alcohol vs Beer Price', children: [] },
          { name: 'Real Income', children: [] },
          { name: 'Unemployment Rate', children: [] },
        ],
      },
      {
        name: 'Weather',
        children: [
          { name: 'Avg Temp', children: [] },
          { name: 'Avg Temp Rolling 8 Weeks', children: [] },
          {
            name: 'Rain',
            children: [
              { name: 'Average Rain', children: [] },
              { name: 'Rain Days', children: [] },
            ],
          },
        ],
      },
    ],
  },
  {
    name: 'Price',
    children: [
      { name: 'Discounted price ratio', children: [] },
      { name: 'Price Index vs ROM Total Industry', children: [] },
      { name: 'Price Ratio Across Brands', children: [] },
      { name: 'Real Price', children: [] },
    ],
  },
  { name: 'Residual', children: [] },
  {
    name: 'Sales & Marketing Investments',
    children: [
      {
        name: 'Marketing',
        children: [
          {
            name: 'All Other Marketing',
            children: [
              { name: 'Experiential', children: [] },
              { name: 'Experiential Corona 100', children: [] },
              { name: 'Influencers', children: [] },
            ],
          },
          {
            name: 'Media',
            children: [
              {
                name: 'Digital',
                children: [
                  { name: 'Caze TV', children: [] },
                  { name: 'Digital Display and Search', children: [] },
                  { name: 'Digital Video', children: [] },
                  { name: 'Globo Digital', children: [] },
                  { name: 'Globo Play', children: [] },
                  { name: 'Netflix', children: [] },
                  {
                    name: 'Socials',
                    children: [
                      { name: 'Meta', children: [] },
                      { name: 'Social Media', children: [] },
                      { name: 'TikTok', children: [] },
                      { name: 'Twitter', children: [] },
                      { name: 'YouTube', children: [] },
                    ],
                  },
                  { name: 'Spotify', children: [] },
                ],
              },
              {
                name: 'Traditional',
                children: [
                  { name: 'Cinema', children: [] },
                  { name: 'OOH', children: [] },
                  { name: 'Open TV', children: [] },
                  { name: 'Pay TV', children: [] },
                  { name: 'Print', children: [] },
                  { name: 'Radio', children: [] },
                ],
              },
            ],
          },
        ],
      },
      {
        name: 'Sales',
        children: [
          {
            name: 'Contracts',
            children: [
              { name: 'Contracts Exclusivity', children: [] },
              { name: 'National Clients', children: [] },
            ],
          },
          { name: 'Merchandiser', children: [] },
          {
            name: 'Trade',
            children: [
              { name: 'Trade Off', children: [] },
              {
                name: 'Trade On',
                children: [
                  { name: 'Trade On Materials', children: [] },
                  { name: 'Trade On Tailor Made', children: [] },
                ],
              },
            ],
          },
        ],
      },
    ],
  },
];

const option = (
  value: string,
  label = value,
): Option & { value: string; label: string } => ({ value, label });

const buildSignalDimensions = (): DefaultOptions[] => {
  const values: Option[][] = Array.from({ length: 6 }, () => []);
  const valuesByParent: Array<Record<string, Option[]>> = Array.from(
    { length: 6 },
    () => ({}),
  );
  const seen: Set<string>[] = Array.from({ length: 6 }, () => new Set());

  const visit = (nodes: SignalNode[], depth: number) => {
    if (depth >= values.length) return;

    nodes.forEach((node) => {
      if (!seen[depth].has(node.name)) {
        seen[depth].add(node.name);
        values[depth].push(option(node.name));
      }

      if (node.children.length > 0 && depth + 1 < values.length) {
        valuesByParent[depth + 1][node.name] = node.children.map((child) =>
          option(child.name),
        );
        visit(node.children, depth + 1);
      }
    });
  };

  visit(signalHierarchy, 0);

  return values.map((levelValues, depth) => ({
    default: null,
    values: levelValues,
    ...(depth > 0 ? { values_by_parent: valuesByParent[depth] } : {}),
    enabled: levelValues.length > 0,
  }));
};

const signalDimensions = buildSignalDimensions();

/**
 * QA-only filter payload derived from the saved WatchTower availabilities
 * response (max_date 2026-07-04). It mirrors the BFF preset shape while M2M
 * authentication is unavailable.
 */
export const watchTowerFilterPreset: FilterDataStructure = {
  kpis: {
    default: option('volume', 'Volume'),
    values: [
      { ...option('volume', 'Volume'), full: 'Volume' },
      { ...option('nr', 'Net Revenue'), full: 'Net Revenue' },
    ],
    enabled: true,
  },
  zones: {
    default: option('SAZ'),
    values: [option('SAZ')],
    enabled: true,
  },
  country: {
    default: option('BRA', 'Brazil'),
    values: {
      SAZ: [option('BRA', 'Brazil')],
    },
    enabled: true,
  },
  region: {
    default: null,
    values: {
      BRA: ['CO', 'MG', 'NE', 'NO', 'RJ-ES', 'SP', 'SUL'].map((value) =>
        option(value),
      ),
    },
    enabled: true,
  },
  watch_tower_brands: {
    default: null,
    values: {
      BRA: {
        default: null,
        brands: [
          option('ANTARCTICA', 'Antarctica'),
          option('BRAHMA', 'Brahma'),
          option('BUDWEISER', 'Budweiser'),
          option('CORONA', 'Corona'),
          option('ORIGINAL', 'Original'),
          option('SKOL', 'Skol'),
          option('SPATEN', 'Spaten'),
          option('STELLA ARTOIS', 'Stella Artois'),
        ],
      },
    },
    enabled: true,
  },
  driver: signalDimensions[0],
  vehicle_level_1: signalDimensions[1],
  vehicle_level_2: signalDimensions[2],
  vehicle_level_3: signalDimensions[3],
  vehicle_level_4: signalDimensions[4],
  vehicle_level_5: signalDimensions[5],
  channel: {
    default: null,
    values: [
      option('OFF (DIRETA)', 'Off (Direta)'),
      option('ON (REVENDA + CDD)', 'On (Revenda + Cdd)'),
    ],
    enabled: true,
  },
  periods: {
    default: {
      ...option('YTD', "YTD Jul'26"),
      full: 'Year to Date (YTD)',
    },
    values: [
      {
        ...option('YTD', "YTD Jul'26"),
        full: 'Year to Date (YTD)',
      },
      {
        ...option('MTD', "Jul'26"),
        full: 'Month to Date (MTD)',
      },
    ],
    enabled: true,
  },
  currency: {
    default: option('lcu', 'LCU (R$)'),
    values: [option('lcu', 'LCU (R$)'), option('usd', 'USD ($)')],
    enabled: true,
  },
};
